/**************************
 * Pod-Level Module Cache Singleton
 **************************/
import { LRUCache } from "../utils/lru-wrapper.js";
import { rendererLogger } from "../utils/index.js";
import { ESM_CACHE_MAX_ENTRIES, ESM_CACHE_TTL_MS, MODULE_CACHE_MAX_ENTRIES, MODULE_CACHE_TTL_MS, } from "../utils/constants/cache.js";
import { registerLRUCache } from "./registry.js";
const logger = rendererLogger.component("module-cache");
let moduleCache = null;
let esmCache = null;
function getOrInitPodCache(options) {
    const existing = options.getExisting();
    if (existing)
        return existing;
    const cache = new LRUCache({
        maxEntries: options.maxEntries,
        ttlMs: options.ttlMs,
    });
    options.assign(cache);
    registerLRUCache(options.registryName, cache);
    logger.debug(options.logMessage, {
        maxEntries: options.maxEntries,
        ttlMs: options.ttlMs,
    });
    return cache;
}
const modulePodCacheOptions = {
    getExisting: () => moduleCache,
    assign: (cache) => {
        moduleCache = cache;
    },
    maxEntries: MODULE_CACHE_MAX_ENTRIES,
    ttlMs: MODULE_CACHE_TTL_MS,
    registryName: "pod-module-cache",
    logMessage: "[ModuleCache] Pod-level module cache initialized",
};
const esmPodCacheOptions = {
    getExisting: () => esmCache,
    assign: (cache) => {
        esmCache = cache;
    },
    maxEntries: ESM_CACHE_MAX_ENTRIES,
    ttlMs: ESM_CACHE_TTL_MS,
    registryName: "pod-esm-cache",
    logMessage: "[ModuleCache] Pod-level ESM cache initialized",
};
export function getModuleCache() {
    return getOrInitPodCache(modulePodCacheOptions);
}
export function getEsmCache() {
    return getOrInitPodCache(esmPodCacheOptions);
}
export function createModuleCache() {
    return createMapInterface(getModuleCache());
}
export function createEsmCache() {
    return createMapInterface(getEsmCache());
}
function createMapInterface(cache) {
    return new LRUBackedMap(cache);
}
function toMapIterator(source) {
    if (typeof Iterator !== "undefined") {
        return Iterator.from(source);
    }
    const snapshot = new Map();
    for (const value of source) {
        snapshot.set(snapshot.size, value);
    }
    return snapshot.values();
}
class LRUBackedMap {
    cache;
    [Symbol.toStringTag] = "Map";
    constructor(cache) {
        this.cache = cache;
    }
    get(key) {
        return this.cache.get(key);
    }
    set(key, value) {
        this.cache.set(key, value);
        return this;
    }
    has(key) {
        return this.cache.has(key);
    }
    delete(key) {
        return this.cache.delete(key);
    }
    clear() {
        this.cache.clear();
    }
    getOrInsert(key, value) {
        const existing = this.cache.get(key);
        if (existing !== undefined)
            return existing;
        this.cache.set(key, value);
        return value;
    }
    getOrInsertComputed(key, callback) {
        const existing = this.cache.get(key);
        if (existing !== undefined)
            return existing;
        const value = callback(key);
        this.cache.set(key, value);
        return value;
    }
    get size() {
        return this.cache.size;
    }
    keys() {
        return toMapIterator(this.cache.keys());
    }
    values() {
        const keysIter = this.cache.keys();
        const cacheRef = this.cache;
        return toMapIterator((function* () {
            for (const key of keysIter) {
                const value = cacheRef.get(key);
                if (value !== undefined)
                    yield value;
            }
        })());
    }
    entries() {
        const keysIter = this.cache.keys();
        const cacheRef = this.cache;
        return toMapIterator((function* () {
            for (const key of keysIter) {
                const value = cacheRef.get(key);
                if (value !== undefined)
                    yield [key, value];
            }
        })());
    }
    forEach(callback, thisArg) {
        for (const [key, value] of this.entries()) {
            callback.call(thisArg, value, key, this);
        }
    }
    [Symbol.iterator]() {
        return this.entries();
    }
}
export function getModuleCacheStats() {
    return {
        moduleCache: {
            size: moduleCache?.size ?? 0,
            maxEntries: MODULE_CACHE_MAX_ENTRIES,
            ttlMs: MODULE_CACHE_TTL_MS,
        },
        esmCache: {
            size: esmCache?.size ?? 0,
            maxEntries: ESM_CACHE_MAX_ENTRIES,
            ttlMs: ESM_CACHE_TTL_MS,
        },
    };
}
export function clearModuleCaches() {
    moduleCache?.clear();
    esmCache?.clear();
    logger.info("All module caches cleared");
}
export function clearModuleCacheForProject(projectId) {
    if (!moduleCache)
        return 0;
    let cleared = 0;
    for (const key of moduleCache.keys()) {
        if (!key.startsWith(`${projectId}:`))
            continue;
        moduleCache.delete(key);
        cleared++;
    }
    if (cleared > 0) {
        logger.info("Cleared module cache for project", { projectId, cleared });
    }
    return cleared;
}
export function destroyModuleCaches() {
    moduleCache?.destroy();
    esmCache?.destroy();
    moduleCache = null;
    esmCache = null;
    logger.info("Module caches destroyed");
}
